// Service worker (generated by shared/pwa/make-pwa.mjs; edit sw-template.js, not the output).
// - Static files: cache-first from a versioned cache.
// - Navigations: network-first, falling back to the cached app shell.
// - /api/* and /ws/* never touch the cache.
// VERSION is a content hash of every precached file, so it changes whenever a file does.
const VERSION = '416816d0c6';
const PREFIX = 'quest-';
const CACHE = PREFIX + VERSION;

const SHELL = '/';
const PRECACHE = [
  '/',
  '/fonts/LICENSE-cinzel.txt',
  '/fonts/LICENSE-rubik.txt',
  '/fonts/alegreya-italic-var.woff2',
  '/fonts/alegreya-sans-400.woff2',
  '/fonts/alegreya-sans-500.woff2',
  '/fonts/alegreya-sans-700.woff2',
  '/fonts/alegreya-sans-800.woff2',
  '/fonts/big-shoulders-display-var.woff2',
  '/fonts/cinzel-600.woff2',
  '/fonts/cinzel-800.woff2',
  '/fonts/cinzel-decorative-700.woff2',
  '/fonts/rubik-var.woff2',
  '/fx.css',
  '/icons/apple-touch-icon.png',
  '/icons/favicon-32.png',
  '/icons/favicon.svg',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/icon-maskable-512.png',
  '/js/app.js',
  '/js/art.js',
  '/js/cards.js',
  '/js/device.js',
  '/js/faq.js',
  '/js/fx.js',
  '/js/glyphs.js',
  '/js/motion.js',
  '/js/print-guide.js',
  '/js/print.js',
  '/js/qr.js',
  '/js/reveal.js',
  '/js/room.js',
  '/js/rules.js',
  '/js/table.js',
  '/js/table_ui.js',
  '/js/ui_icons.js',
  '/manifest.webmanifest',
  '/motion.css',
  '/print.css',
  '/print.html',
  '/print/quest-night-card-guide.pdf',
  '/print/quest-night-cards.pdf',
  '/pwa-install.js',
  '/styles.css',
  '/theme.css',
];

const isLive = (url) => url.pathname.startsWith('/api/') || url.pathname.startsWith('/ws/');
// A redirected response cannot answer a navigation, so only plain 200s are stored.
const storable = (res) => res && res.ok && res.status === 200 && !res.redirected && res.type === 'basic';

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // One file at a time, so a single missing file never blocks the install.
    await Promise.allSettled(PRECACHE.map(async (path) => {
      const res = await fetch(path, { cache: 'reload' });
      if (storable(res)) await cache.put(path, res);
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || isLive(url)) return; // network only

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const res = await fetch(req);
        if (url.pathname === SHELL && storable(res)) {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put(SHELL, copy));
        }
        return res;
      } catch {
        return (await caches.match(SHELL)) || Response.error();
      }
    })());
    return;
  }

  event.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const res = await fetch(req);
    if (storable(res)) {
      const copy = res.clone();
      caches.open(CACHE).then((c) => c.put(req, copy));
    }
    return res;
  })());
});
